    // -------------------------------------------------------------------------
    // Main entry mapper
    // -------------------------------------------------------------------------

    /**
     * Map a raw WPForms entry array to structured DB-ready data.
     *
     * @param  array $entry  Raw WPForms entry (fields keyed by field ID).
     * @return array {
     *     'players'       => [ column => value, ... ],
     *     'registrations' => [ column => value, ... ],
     *     'availability'  => [ column => value, ... ] | null,
     *     'warnings'      => [ string, ... ],
     *     'errors'        => [ string, ... ],
     * }
     */
    public function map_entry( array $entry ): array {

        $result = [
            self::TABLE_PLAYERS       => [ 'season_id' => self::SEASON ],
            self::TABLE_REGISTRATIONS => [
                'season_id' => self::SEASON,
                'form_id'   => self::FORM_ID,
                'source'    => 'wpforms',
            ],
            self::TABLE_AVAILABILITY  => null,
            'warnings'                => [],
            'errors'                  => [],
        ];

        $field_map  = $this->get_field_map();
        $is_sub     = $this->is_sub( $entry );

        // Initialise availability row for subs
        if ( $is_sub ) {
            $result[ self::TABLE_AVAILABILITY ] = [
                'season_id'   => self::SEASON,
                'player_type' => 'sub',
            ];
        }

        foreach ( $field_map as $key => $map ) {

            // Multi-field entries (waiver)
            $field_ids = $map['field_ids'] ?? [ $map['field_id'] ];
            $raw_values = [];
            foreach ( $field_ids as $fid ) {
                $raw_values[ $fid ] = $entry['fields'][ $fid ]['value'] ?? null;
            }
            $raw = count( $raw_values ) === 1
                ? reset( $raw_values )
                : $raw_values;

            // Apply subkey (name field)
            if ( isset( $map['subkey'] ) && is_array( $raw ) ) {
                $raw = $raw[ $map['subkey'] ] ?? null;
            }

            // Apply transform
            if ( isset( $map['transform'] ) && is_callable( $map['transform'] ) ) {
                $value = call_user_func( $map['transform'], $raw, $entry );
            } else {
                $value = $this->cast( $raw, $map['type'] );
            }

            // Required check
            if ( $map['required'] && ( $value === null || $value === '' ) ) {
                // Only flag as error if field was expected for this player type
                $skip_for_sub = in_array( $map['field_id'] ?? '', [ '83', '47', '44', '64', '65' ] );
                if ( ! ( $is_sub && $skip_for_sub ) ) {
                    $result['errors'][] = "Missing required field: {$key} (field ID: " . ( $map['field_id'] ?? implode( ',', $field_ids ) ) . ')';
                }
            }

            // Write to target table
            if ( $value !== null ) {
                $table = $map['table'];
                if ( $table === self::TABLE_AVAILABILITY && ! $is_sub ) {
                    continue; // availability only for subs
                }
                $result[ $table ][ $map['column'] ] = $value;
            }
        }

        // Sandbagging check
        $result['warnings'] = array_merge(
            $result['warnings'],
            $this->run_sandbagging_check( $result )
        );

        return $result;
    }

    // -------------------------------------------------------------------------
    // Transform methods
    // -------------------------------------------------------------------------

    public function transform_player_type( $raw ): string {
        return str_contains( strtolower( (string) $raw ), 'sub' ) ? 'sub' : 'primary';
    }

    public function transform_is_alternate( $raw ): bool {
        return str_contains( strtolower( (string) $raw ), 'sub' );
    }

    public function transform_division( $raw ): string {
        $map = [
            'Gold Open'  => 'gold_open',
            '45A'        => '45a',
            'Senior B'   => 'senior_b',
            'Senior C'   => 'senior_c',
        ];
        foreach ( $map as $label => $slug ) {
            if ( str_contains( $raw, $label ) ) {
                return $slug;
            }
        }
        return sanitize_key( $raw );
    }

    public function transform_skill_tier( $raw ): string {
        // Extract the tier code from the start of the label e.g. "R2 - Recreational..."
        if ( preg_match( '/^([A-Z][0-9])/', trim( (string) $raw ), $m ) ) {
            return $m[1];
        }
        return strtoupper( substr( trim( (string) $raw ), 0, 2 ) );
    }

    public function transform_league( $raw ): string {
        $map = [
            'Bronze B (Entry Level)' => 'bronze_b',
            'Gold'                   => 'gold',
            'O45 A'                  => 'o45_a',
            '50 B'                   => '50_b',
            'Silver A'               => 'silver_a',
            'Silver B'               => 'silver_b',
            'Other'                  => 'other',
        ];
        return $map[ trim( (string) $raw ) ] ?? sanitize_key( $raw );
    }

    public function transform_position( $raw ): string {
        $map = [
            'Defenseman' => 'defenseman',
            'Center'     => 'center',
            'Winger'     => 'winger',
            'Goaltender' => 'goaltender',
        ];
        return $map[ trim( (string) $raw ) ] ?? sanitize_key( $raw );
    }

    public function transform_availability_days( $raw ): string {
        // WPForms checkbox returns comma-separated labels
        $days = array_map(
            fn( $d ) => strtolower( trim( $d ) ),
            explode( "\n", (string) $raw )
        );
        $days = array_filter( $days );
        return wp_json_encode( array_values( $days ) );
    }

    public function transform_division_eligibility( $raw ): string {
        $slugs = [
            'Womens'   => 'womens',
            'Gold Open' => 'gold_open',
            'O45 A'    => 'o45_a',
            'Senior B' => 'senior_b',
            'Senior C' => 'senior_c',
        ];
        $selected = [];
        foreach ( $slugs as $label => $slug ) {
            if ( str_contains( (string) $raw, $label ) ) {
                $selected[] = $slug;
            }
        }
        return wp_json_encode( $selected );
    }

    public function transform_yes_no( $raw ): bool {
        return strtolower( trim( (string) $raw ) ) === 'yes';
    }

    public function transform_payment_method( $raw, array $entry ): string {
        $player_type = $entry['fields']['84']['value'] ?? '';
        if ( str_contains( strtolower( $player_type ), 'sub' ) ) {
            return 'waived';
        }
        // WPForms PayPal Commerce stores method in meta
        $method = $entry['meta']['payment_type'] ?? 'paypal';
        return str_contains( $method, 'card' ) ? 'credit_card' : 'paypal';
    }

    public function transform_payment_status( $raw, array $entry ): string {
        $player_type = $entry['fields']['84']['value'] ?? '';
        if ( str_contains( strtolower( $player_type ), 'sub' ) ) {
            return 'waived';
        }
        $status = $entry['meta']['payment_status'] ?? 'pending';
        return in_array( $status, [ 'paid', 'pending', 'refunded' ], true )
            ? $status
            : 'pending';
    }

    public function transform_waiver( $raw_values ): bool {
        // All 8 checkboxes must be checked
        foreach ( $raw_values as $val ) {
            if ( empty( $val ) ) {
                return false;
            }
        }
        return true;
    }

    // -------------------------------------------------------------------------
    // Sandbagging check
    // -------------------------------------------------------------------------

    private function run_sandbagging_check( array $result ): array {
        $warnings = [];
        $tier      = $result[ self::TABLE_PLAYERS ]['skill_tier_reported'] ?? null;
        $division  = $result[ self::TABLE_REGISTRATIONS ]['division_requested'] ?? null;

        if ( ! $tier || ! $division ) {
            return $warnings;
        }

        // High-skill tiers requesting lower divisions
        $high_tiers     = [ 'A1', 'A2', 'A3', 'B1', 'B2' ];
        $lower_divisions = [ 'senior_b', 'senior_c' ];

        if ( in_array( $tier, $high_tiers, true ) && in_array( $division, $lower_divisions, true ) ) {
            $warnings[] = "SANDBAGGING_REVIEW: Player skill tier {$tier} requested division {$division} — committee review required.";
        }

        return $warnings;
    }

    // -------------------------------------------------------------------------
    // Helpers
    // -------------------------------------------------------------------------

    private function is_sub( array $entry ): bool {
        $val = $entry['fields']['84']['value'] ?? '';
        return str_contains( strtolower( (string) $val ), 'sub' );
    }

    private function cast( $value, string $type ) {
        if ( $value === null || $value === '' ) {
            return null;
        }
        return match ( $type ) {
            'integer' => (int) $value,
            'decimal' => (float) $value,
            'boolean' => (bool) $value,
            'email'   => sanitize_email( $value ),
            'string'  => sanitize_text_field( $value ),
            default   => $value,
        };
    }
}
